def transform(grid):
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    out=[row[:] for row in grid]
    # This pattern draws the orthogonal hull/network of points: connect each
    # marker to its nearest neighbor on the same row/column; for the remaining
    # diagonally placed points, use the shortest Manhattan elbow.
    n=len(pts); edges=[]
    for i,(r,c) in enumerate(pts):
        for j,(rr,cc) in enumerate(pts[i+1:],i+1):
            if r==rr or c==cc: edges.append((abs(r-rr)+abs(c-cc),i,j))
    parent=list(range(n))
    def root(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]; x=parent[x]
        return x
    for _,i,j in sorted(edges):
        a,b=root(i),root(j)
        if a==b: continue
        parent[a]=b
        r,c=pts[i]; rr,cc=pts[j]
        if r==rr:
            for x in range(min(c,cc),max(c,cc)+1):
                if out[r][x]==0: out[r][x]=3
        else:
            for y in range(min(r,rr),max(r,rr)+1):
                if out[y][c]==0: out[y][c]=3
    return out
