 "content": "def transform(grid):
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    # Connect the aligned pair on the central row, then join the remaining
    # markers by shortest orthogonal branches into that line/tree.
    byrow={}
    for r,c in pts: byrow.setdefault(r,[]).append(c)
    for r,cs in byrow.items():
        if len(cs)>1:
            for c in range(min(cs),max(cs)+1):
                if out[r][c]==0: out[r][c]=3
    # For each marker not already connected, attach through the nearest
    # rectilinear path to the existing colored network or another marker.
    # This ordered path rule matches the common spine/branch constructions.
    # Start with existing row connections; repeatedly attach nearest point.
    connected=set()
    for r,cs in byrow.items():
        if len(cs)>1: connected.update((r,c) for c in cs)
    if not connected and pts: connected.add(pts[0])
    pending=[p for p in pts if p not in connected]
    while pending:
        best=None
        for p in pending:
            r,c=p
            for y,x in connected:
                d=abs(r-y)+abs(c-x)
                cand=(d,p,(y,x))
                if best is None or cand<best: best=cand
        _,(r,c),(y,x)=best
        # route via closer of the two elbows, favor reuse of colored network
        routes=[[(r,k) for k in range(min(c,x),max(c,x)+1)]+[(k,x) for k in range(min(r,y),max(r,y)+1)],
                [(k,c) for k in range(min(r,y),max(r,y)+1)]+[(y,k) for k in range(min(c,x),max(c,x)+1)]]
        route=min(routes,key=lambda z:sum(out[a][b]==0 for a,b in set(z)))
        for a,b in route:
            if out[a][b]==0: out[a][b]=3
        connected.add((r,c)); pending.remove((r,c))
        # Add all colored cells as the available network for subsequent joins.
        connected.update((a,b) for a,row in enumerate(out) for b,v in enumerate(row) if v==3)
    return out
