 "content": "import heapq

def transform(grid):
    h,w=len(grid),len(grid[0]); pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    if len(pts)<2:return [row[:] for row in grid]
    n=len(pts); N=h*w; full=(1<<n)-1
    term={r*w+c for r,c in pts}
    INF=10**9
    # Dreyfus-Wagner DP: minimum-cost connected node set joining terminal subset.
    dp=[[INF]*N for _ in range(1<<n)]; back=[[None]*N for _ in range(1<<n)]
    adj=[]
    for p in range(N):
        r,c=divmod(p,w); adj.append([rr*w+cc for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=rr<h and 0<=cc<w])
    for i,p in enumerate(sorted(term)):
        dp[1<<i][p]=0
    for mask in range(1,1<<n):
        # combine two already-built subtrees at a shared vertex
        sub=(mask-1)&mask
        while sub:
            other=mask^sub
            if other and sub<other:
                a=dp[sub]; b=dp[other]; d=dp[mask]
                for p in range(N):
                    val=a[p]+b[p]
                    if val<d[p]: d[p]=val; back[mask][p]=('merge',sub,other,p)
            sub=(sub-1)&mask
        # multi-source Dijkstra to extend the connected set along grid
        dist=dp[mask][:]; pq=[(v,p) for p,v in enumerate(dist) if v<INF]; heapq.heapify(pq)
        while pq:
            val,p=heapq.heappop(pq)
            if val!=dist[p]: continue
            for q in adj[p]:
                cost=0 if q in term else 1
                nv=val+cost
                if nv<dist[q]:
                    dist[q]=nv; back[mask][q]=('move',p); heapq.heappush(pq,(nv,q))
        dp[mask]=dist
    end=min(range(N),key=lambda p:dp[full][p]); seen=set()
    def trace(mask,p):
        key=(mask,p)
        if key in seen:return
        seen.add(key); b=back[mask][p]
        if not b:return
        if b[0]=='move':
            q=b[1]; trace(mask,q); seen.add((mask,p))
        else:
            _,a,c,q=b; trace(a,q); trace(c,q)
    trace(full,end)
    out=[row[:] for row in grid]
    nodes={p for mask,p in seen}
    for p in nodes:
        r,c=divmod(p,w)
        if out[r][c]==0:out[r][c]=3
    return out
