    # Demo-consistent rule: connect points by vertical stems to the lower
    # median marker row and join those stems with a horizontal bar.
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    out=[row[:] for row in grid]
    if not pts:
        return out
    rows=sorted(r for r,c in pts)
    spine=rows[(len(rows)-1)//2]
    left=min(c for r,c in pts)
    right=max(c for r,c in pts)
    for c in range(left,right+1):
        if out[spine][c]==0:
            out[spine][c]=3
    for r,c in pts:
        for y in range(min(r,spine),max(r,spine)+1):
            if out[y][c]==0:
                out[y][c]=3
    return out
